 for(String text:new String[]{"駅じゃなくて市役所","駅ではなく市役所","駅でなく市役所にして"}){ok(NavigationExperiencePolicy.replacement(text,true).equals("市役所"));ok(NavigationExperiencePolicy.replacement(text,false).isEmpty());}
 for(String text:new String[]{"駅じゃなくて","駅じゃなくて市役所にしないで","「駅じゃなくて市役所」って言った場合","いつもの天気を教えて"})ok(NavigationExperiencePolicy.replacement(text,true).isEmpty());
 ok(NavigationExperiencePolicy.cancelStopover("コンビニはやめる",true));ok(!NavigationExperiencePolicy.cancelStopover("コンビニはやめる",false));ok(NavigationExperiencePolicy.cancelStopover("立ち寄りを取り消して",true));ok(!NavigationExperiencePolicy.cancelStopover("コンビニはやめない",true));
 for(String text:new String[]{"この道は通れない","別の道にしたい","別の経路にしたい","別ルートを確認して"})ok(NavigationExperiencePolicy.alternative(text));for(String text:new String[]{"別の道にしたいと言ったらどうなる","別の道にしないで","この道は通れる"})ok(!NavigationExperiencePolicy.alternative(text));
 ok(NavigationExperiencePolicy.trouble("LINK").contains("スマホ"));ok(NavigationExperiencePolicy.trouble("LOCATION").contains("GPS"));ok(NavigationExperiencePolicy.trouble("ROUTE").contains("経路取得"));ok(NavigationExperiencePolicy.trouble("ROUTE_MISSING").contains("未取得"));ok(NavigationExperiencePolicy.trouble("UPDATING").contains("更新中"));ok(NavigationExperiencePolicy.trouble("").isEmpty());
 ok(NavigationAlternativePolicy.trouble(true,true,false,false).equals("ROUTE"));ok(NavigationAlternativePolicy.trouble(false,false,false,true).equals("LOCATION"));ok(NavigationAlternativePolicy.trouble(true,false,true,false).equals("UPDATING"));ok(NavigationAlternativePolicy.trouble(true,false,false,false).equals("ROUTE_MISSING"));ok(NavigationAlternativePolicy.trouble(true,false,false,true).isEmpty());
